import{_ as t,o as d,c as n,a3 as i}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Kacheln und Karten","description":"Inhalte für Tabs vom Typ TilesGrid und CardList pflegen — inklusive der Aktionstypen.","frontmatter":{"title":"Kacheln und Karten","description":"Inhalte für Tabs vom Typ TilesGrid und CardList pflegen — inklusive der Aktionstypen."},"headers":[],"relativePath":"apptiveteams/kacheln-und-karten.md","filePath":"apptiveteams/kacheln-und-karten.md","lastUpdated":1786357627000}'),r={name:"apptiveteams/kacheln-und-karten.md"};function a(l,e,s,o,c,h){return d(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="kacheln-und-karten" tabindex="-1">Kacheln und Karten <a class="header-anchor" href="#kacheln-und-karten" aria-label="Permalink to &quot;Kacheln und Karten&quot;">​</a></h1><p>Tabs vom Typ <code>TilesGrid</code> und <code>CardList</code> beziehen ihre Inhalte aus dem Grid, das im Tab über <code>gridUri</code> verknüpft ist. Jede Zeile dieses Grids wird zu einer Kachel bzw. Karte.</p><h2 id="kachel-ansicht-tilesgrid" tabindex="-1">Kachel-Ansicht <code>TilesGrid</code> <a class="header-anchor" href="#kachel-ansicht-tilesgrid" aria-label="Permalink to &quot;Kachel-Ansicht `TilesGrid`&quot;">​</a></h2><p>Ein Raster aus Kacheln — der übliche Startbildschirm mit Schnellzugriffen auf Formulare und Links.</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>title</code></td><td>Text</td><td>ja</td><td>Beschriftung der Kachel</td></tr><tr><td><code>icon</code></td><td>Anhang (SVG)</td><td>ja</td><td>Icon der Kachel, einfarbiges SVG</td></tr><tr><td><code>uri</code></td><td>Weblink</td><td>ja</td><td>Ziel der Kachel, etwa ein Formular-Link</td></tr><tr><td><code>actionType</code></td><td>Text / Einzelauswahl</td><td>ja</td><td>Wie das Ziel geöffnet wird — siehe unten</td></tr></tbody></table><h2 id="karten-ansicht-cardlist" tabindex="-1">Karten-Ansicht <code>CardList</code> <a class="header-anchor" href="#karten-ansicht-cardlist" aria-label="Permalink to &quot;Karten-Ansicht `CardList`&quot;">​</a></h2><p>Eine Liste aus Karten mit Bild, Überschrift und Aktions-Button — für Neuigkeiten, Ankündigungen oder Aufgaben.</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>headline</code></td><td>Text</td><td>ja</td><td>Überschrift der Karte</td></tr><tr><td><code>supportingText</code></td><td>Text</td><td>nein</td><td>Beschreibungstext unter der Überschrift</td></tr><tr><td><code>image</code></td><td>Anhang (Bild)</td><td>nein</td><td>Bild der Karte</td></tr><tr><td><code>actionUri</code></td><td>Weblink</td><td>ja</td><td>Ziel des Aktions-Buttons</td></tr><tr><td><code>actionType</code></td><td>Text / Einzelauswahl</td><td>ja</td><td>Wie das Ziel geöffnet wird — siehe unten</td></tr><tr><td><code>actionLabel</code></td><td>Text</td><td>nein</td><td>Beschriftung des Aktions-Buttons</td></tr><tr><td><code>createdAt</code></td><td>Datum und Uhrzeit</td><td>ja</td><td>Wird auf der Karte angezeigt, etwa als „Heute&quot; oder „Gestern&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title"><code>createdAt</code> automatisch füllen lassen</p><p>Legen Sie das Feld als Spaltentyp <strong>Erstellt am</strong> an. Dann wird es bei jedem neuen Eintrag automatisch gesetzt — auch bei Einträgen, die über ein Formular oder einen Flow entstehen. → <a href="/referenz/spaltentypen">Spaltentypen</a></p></div><h2 id="aktionstypen" tabindex="-1">Aktionstypen <a class="header-anchor" href="#aktionstypen" aria-label="Permalink to &quot;Aktionstypen&quot;">​</a></h2><p>Der Wert in <code>actionType</code> entscheidet, wie das Ziel geöffnet wird.</p><table tabindex="0"><thead><tr><th>Wert</th><th>Verhalten</th><th>Kacheln</th><th>Karten</th></tr></thead><tbody><tr><td><code>formLink</code></td><td>Öffnet ein ApptiveGrid-Formular direkt in der App</td><td>✓</td><td>✓</td></tr><tr><td><code>internalLink</code></td><td>Öffnet die Seite innerhalb der App</td><td>✓</td><td>✓</td></tr><tr><td><code>externalLink</code></td><td>Öffnet die Seite im Browser des Geräts</td><td>✓</td><td>✓</td></tr><tr><td><code>triggerFlow</code></td><td>Öffnet das Ziel in einem In-App-Browser</td><td>–</td><td>✓</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title"><code>internalLink</code> überträgt, wer angemeldet ist</p><p>Bei ApptiveGrid-Links übergibt <code>internalLink</code> die angemeldete Person mit. Ein darüber ausgefülltes Formular trägt dadurch im Feld <strong>Erstellt von</strong> die richtige Person statt „Formular-Link&quot;.</p><p>Wenn Sie nachvollziehen wollen, wer eine Meldung abgesetzt hat, ist das der entscheidende Unterschied zu <code>externalLink</code>.</p></div><p><code>triggerFlow</code> gibt es nur bei Karten. Damit starten Sie einen ApptiveGrid-Flow direkt aus einer Karte heraus. → <a href="/flows/webhook-trigger">Flow per Webhook starten</a></p><h2 id="zeilen-mit-lucken-werden-ubersprungen" tabindex="-1">Zeilen mit Lücken werden übersprungen <a class="header-anchor" href="#zeilen-mit-lucken-werden-ubersprungen" aria-label="Permalink to &quot;Zeilen mit Lücken werden übersprungen&quot;">​</a></h2><p>Wie bei den Tabs gilt: Fehlt ein Pflichtfeld, erscheint die Kachel bzw. Karte nicht — ohne Meldung. Fehlt eine Kachel unerwartet, prüfen Sie zuerst die Pflichtfelder und dann die Schreibweise der Feld-Keys.</p><div class="tip custom-block"><p class="custom-block-title">Reihenfolge über eine sortierte Ansicht steuern</p><p>Kacheln und Karten erscheinen in der Reihenfolge des verknüpften Grids. Verknüpfen Sie eine <strong>Ansicht</strong> statt des Grids, steuern Sie Reihenfolge und Sichtbarkeit über deren Sortierung und Filter — bei Neuigkeiten etwa absteigend nach Datum.</p><p>→ <a href="/ansichten/filtern-sortieren-gruppieren">Filtern, sortieren und gruppieren</a></p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/apptiveteams/einstellungen">Einstellungs-Bildschirm ergänzen</a></li><li><a href="/apptiveteams/fehlerbehebung">Tipps und Fehlerbehebung</a></li></ul>',19)])])}const b=t(r,[["render",a]]);export{p as __pageData,b as default};
